class Get_User_Contributions_Articles(API_base):
    """
    Retrieves a list of user contributions (articles) related to a specific user.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_id", "p_sort", "p_next_cursor", "p_per_page", "p_text_format"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_id = params.get('p_id', None)
        if p_id is None:
            return self.handle_error(f"Required parameter 'p_id' is missing", 400)
        is_valid, error = self.validate_type(p_id, 'p_id', str)
        if not is_valid:
            return error
        
        p_sort = params.get('p_sort', None)
        if p_sort is not None:
            is_valid, error = self.validate_type(p_sort, 'p_sort', str)
            if not is_valid:
                return error
        
        p_next_cursor = params.get('p_next_cursor', None)
        if p_next_cursor is not None:
            is_valid, error = self.validate_type(p_next_cursor, 'p_next_cursor', str)
            if not is_valid:
                return error
        
        p_per_page = params.get('p_per_page', None)
        if p_per_page is not None:
            is_valid, error = self.validate_type(p_per_page, 'p_per_page', (float, int))
            if not is_valid:
                return error
        if p_per_page is not None:
            p_per_page = float(p_per_page)
        
        p_text_format = params.get('p_text_format', None)
        if p_text_format is not None:
            is_valid, error = self.validate_type(p_text_format, 'p_text_format', str)
            if not is_valid:
                return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Get_User_Contributions_Articles",
                "p_id": p_id,
                "p_sort": p_sort,
                "p_next_cursor": p_next_cursor,
                "p_per_page": p_per_page,
                "p_text_format": p_text_format
            }
        }

class SearchStation(API_base):
    """
    Search for radio stations by keyword. Returns a list of radio stations that match the search query.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_keyword", "p_order", "p_page", "p_limit"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_keyword = params.get('p_keyword', None)
        if p_keyword is None:
            return self.handle_error(f"Required parameter 'p_keyword' is missing", 400)
        is_valid, error = self.validate_type(p_keyword, 'p_keyword', str)
        if not is_valid:
            return error
        
        p_order = params.get('p_order', None)
        if p_order is not None:
            is_valid, error = self.validate_type(p_order, 'p_order', str)
            if not is_valid:
                return error
        
        if p_order is not None and p_order not in ["ASC", "DESC"]:
            return self.handle_error(f"Parameter 'p_order' not in valid enum", 400)
        
        p_page = params.get('p_page', None)
        if p_page is not None:
            is_valid, error = self.validate_type(p_page, 'p_page', (float, int))
            if not is_valid:
                return error
        if p_page is not None:
            p_page = float(p_page)
        
        p_limit = params.get('p_limit', None)
        if p_limit is not None:
            is_valid, error = self.validate_type(p_limit, 'p_limit', (float, int))
            if not is_valid:
                return error
        if p_limit is not None:
            p_limit = float(p_limit)
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "SearchStation",
                "p_keyword": p_keyword,
                "p_order": p_order,
                "p_page": p_page,
                "p_limit": p_limit
            }
        }

