class HealthData_fetchRegionalStatistics(API_base):
    """
    Fetches detailed COVID-19 statistics for a specific region including active cases, recovered cases, and deaths.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_regionInfo"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_regionInfo = params.get('p_regionInfo', None)
        if p_regionInfo is not None:
            is_valid, error = self.validate_type(p_regionInfo, 'p_regionInfo', dict)
            if not is_valid:
                return error
        
        if p_regionInfo is not None:

            p_regionCode = p_regionInfo.get('p_regionCode', None)
            if p_regionCode is None:
                return self.handle_error(f"Required parameter 'p_regionCode' is missing", 400)
            is_valid, error = self.validate_type(p_regionCode, 'p_regionCode', str)
            if not is_valid:
                return error
            
            p_statisticsType = p_regionInfo.get('p_statisticsType', None)
            if p_statisticsType is None:
                return self.handle_error(f"Required parameter 'p_statisticsType' is missing", 400)
            is_valid, error = self.validate_type(p_statisticsType, 'p_statisticsType', list)
            if not is_valid:
                return error
            
            p_timeFrame = p_regionInfo.get('p_timeFrame', None)
            if p_timeFrame is not None:
                is_valid, error = self.validate_type(p_timeFrame, 'p_timeFrame', str)
                if not is_valid:
                    return error
            
        return {
            "status_code": 200, 
            "results": {
                "function_name": "HealthData_fetchRegionalStatistics",
                "p_regionInfo": p_regionInfo
            }
        }

