class Get_YouTube_Video_Comments(API_base):
    """
    Retrieve comments for a specific YouTube video.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_part", "p_id", "p_maxResults", "p_parentId"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_part = params.get('p_part', None)
        if p_part is None:
            return self.handle_error(f"Required parameter 'p_part' is missing", 400)
        is_valid, error = self.validate_type(p_part, 'p_part', str)
        if not is_valid:
            return error
        
        p_id = params.get('p_id', None)
        if p_id is None:
            return self.handle_error(f"Required parameter 'p_id' is missing", 400)
        is_valid, error = self.validate_type(p_id, 'p_id', str)
        if not is_valid:
            return error
        
        _default_p_maxResults = int("") if "" !=  ""  else 0
        p_maxResults = params.get('p_maxResults', _default_p_maxResults)
        if p_maxResults is not None:
            is_valid, error = self.validate_type(p_maxResults, 'p_maxResults', int)
            if not is_valid:
                return error
        
        p_parentId = params.get('p_parentId', "")
        if p_parentId is not None:
            is_valid, error = self.validate_type(p_parentId, 'p_parentId', str)
            if not is_valid:
                return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Get_YouTube_Video_Comments",
                "p_part": p_part,
                "p_id": p_id,
                "p_maxResults": p_maxResults,
                "p_parentId": p_parentId
            }
        }

